const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'cover',
  index: 1,
  title: 'Scale SEAL Leaderboards'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Decorative accent shapes - right side geometric blocks representing data/benchmarks
  const colors = ["2a9d8f", "e9c46a", "f4a261", "e76f51"];
  const blockX = 6.8;
  for (let i = 0; i < 4; i++) {
    slide.addShape(pres.shapes.RECTANGLE, {
      x: blockX + i * 0.7,
      y: 0.8,
      w: 0.55,
      h: 0.25 + i * 0.35,
      fill: { color: colors[i] },
      transparency: 25
    });
  }

  // Additional geometric blocks - bottom right
  for (let i = 0; i < 4; i++) {
    slide.addShape(pres.shapes.RECTANGLE, {
      x: blockX + i * 0.7,
      y: 3.8,
      w: 0.55,
      h: 0.25 + (3 - i) * 0.35,
      fill: { color: colors[i] },
      transparency: 40
    });
  }

  // Thin accent line
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 1.8, w: 1.2, h: 0.06,
    fill: { color: theme.accent }
  });

  // Main title
  slide.addText("Scale SEAL Leaderboards", {
    x: 0.6, y: 2.0, w: 6, h: 1.0,
    fontSize: 44, fontFace: "Georgia",
    color: "FFFFFF", bold: true,
    margin: 0
  });

  // Subtitle
  slide.addText("Frontier Model Performance\nAcross 20+ Benchmarks", {
    x: 0.6, y: 3.0, w: 5.5, h: 0.9,
    fontSize: 22, fontFace: "Calibri",
    color: theme.accent,
    margin: 0
  });

  // Description line
  slide.addText("100+ models evaluated across agentic, frontier, safety, and multimodal capabilities", {
    x: 0.6, y: 4.1, w: 5.5, h: 0.5,
    fontSize: 14, fontFace: "Calibri",
    color: "B0C4D8",
    margin: 0
  });

  // Source attribution
  slide.addText("Source: scale.com/leaderboard", {
    x: 0.6, y: 5.0, w: 3, h: 0.3,
    fontSize: 10, fontFace: "Calibri",
    color: "7A9BB5",
    margin: 0
  });

  // Lab color legend at bottom
  const labNames = ["OpenAI", "Google", "Anthropic", "Muse Spark"];
  const labColors = ["264653", "2a9d8f", "e9c46a", "e76f51"];
  // Using theme primary for OpenAI (on dark bg, need lighter), adjust
  const legendColors = ["5BA4C4", "2a9d8f", "e9c46a", "e76f51"];
  for (let i = 0; i < 4; i++) {
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 5.5 + i * 1.15, y: 5.05, w: 0.2, h: 0.2,
      fill: { color: legendColors[i] },
      rectRadius: 0.02
    });
    slide.addText(labNames[i], {
      x: 5.72 + i * 1.15, y: 5.02, w: 0.95, h: 0.25,
      fontSize: 9, fontFace: "Calibri",
      color: "B0C4D8",
      margin: 0
    });
  }

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "264653", secondary: "2a9d8f", accent: "e9c46a", light: "f4a261", bg: "f7f7f7" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-01-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

