const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 2,
  title: '20+ Benchmarks Spanning Four Capability Domains'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("20+ Benchmarks Spanning Four Capability Domains", {
    x: 0.4, y: 0.25, w: 9, h: 0.55,
    fontSize: 28, fontFace: "Georgia",
    color: theme.primary, bold: true,
    margin: 0
  });

  // Subtitle
  slide.addText("Evaluate 100+ models across agentic coding, frontier reasoning, safety alignment, and multimodal understanding", {
    x: 0.4, y: 0.8, w: 9, h: 0.35,
    fontSize: 13, fontFace: "Calibri",
    color: "5A6B7C",
    margin: 0
  });

  // Four category cards in 2x2 grid
  const categories = [
    {
      name: "AGENTIC",
      color: theme.primary,
      benchmarks: ["SWE Atlas - Test Writing", "SWE Atlas - Codebase QnA", "MCP Atlas (Tool Use)", "SWE-Bench Pro (Public)", "SWE-Bench Pro (Private)"],
      icon: ">{ }"
    },
    {
      name: "FRONTIER",
      color: theme.secondary,
      benchmarks: ["Humanity's Last Exam", "HLE (Text Only)", "EnigmaEval", "MultiChallenge", "MultiNRC", "SciPredict"],
      icon: "✦"
    },
    {
      name: "SAFETY",
      color: theme.accent,
      benchmarks: ["MASK (Honesty)", "PropensityBench", "Fortress (NatSec)", "Prof. Reasoning - Legal", "Prof. Reasoning - Finance", "Remote Labor Index"],
      icon: "◐"
    },
    {
      name: "MULTIMODAL",
      color: "e76f51",
      benchmarks: ["AudioMultiChallenge (Text)", "AudioMultiChallenge (Audio)", "VISTA", "VisualToolBench"],
      icon: "◈"
    }
  ];

  const cardW = 4.35;
  const cardH = 1.95;
  const startX = 0.4;
  const startY = 1.35;
  const gapX = 0.5;
  const gapY = 0.35;

  for (let i = 0; i < 4; i++) {
    const cat = categories[i];
    const col = i % 2;
    const row = Math.floor(i / 2);
    const cx = startX + col * (cardW + gapX);
    const cy = startY + row * (cardH + gapY);

    // Card background
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: cy, w: cardW, h: cardH,
      fill: { color: "FFFFFF" },
      shadow: { type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.08 },
      rectRadius: 0.05
    });

    // Top accent bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: cy, w: cardW, h: 0.06,
      fill: { color: cat.color },
      rectRadius: 0
    });

    // Category name + icon
    slide.addText([
      { text: cat.icon + "  ", options: { fontSize: 14, color: cat.color } },
      { text: cat.name, options: { fontSize: 16, bold: true, fontFace: "Georgia", color: theme.primary } }
    ], {
      x: cx + 0.2, y: cy + 0.15, w: cardW - 0.4, h: 0.35,
      margin: 0
    });

    // Benchmark list
    const benchmarkTexts = cat.benchmarks.map((b, idx) => ({
      text: b,
      options: {
        bullet: true,
        breakLine: idx < cat.benchmarks.length - 1,
        fontSize: 10,
        fontFace: "Calibri",
        color: "5A6B7C"
      }
    }));

    slide.addText(benchmarkTexts, {
      x: cx + 0.25, y: cy + 0.55, w: cardW - 0.5, h: cardH - 0.7,
      margin: 0,
      paraSpaceAfter: 2
    });
  }

  // Footer note
  slide.addText("All scores include confidence intervals. Private datasets prevent overfitting; open-source datasets enable comparability.", {
    x: 0.4, y: 5.2, w: 8.5, h: 0.25,
    fontSize: 9, fontFace: "Calibri",
    color: "8A9BAC",
    margin: 0
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.secondary }
  });
  slide.addText("2", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Calibri",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "264653", secondary: "2a9d8f", accent: "e9c46a", light: "f4a261", bg: "f7f7f7" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-02-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

