const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 3,
  title: 'GPT-5.4 Dominates Agentic Coding'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("GPT-5.4 Dominates Agentic Coding: Top Scores on SWE Atlas and SWE-Bench Pro", {
    x: 0.4, y: 0.2, w: 9.2, h: 0.55,
    fontSize: 24, fontFace: "Georgia",
    color: theme.primary, bold: true,
    margin: 0, fit: "shrink"
  });

  // Lab color legend
  const labs = [
    { name: "OpenAI", color: theme.primary },
    { name: "Google", color: theme.secondary },
    { name: "Anthropic", color: theme.accent },
    { name: "Muse Spark", color: "e76f51" }
  ];
  for (let i = 0; i < labs.length; i++) {
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.4 + i * 1.3, y: 0.82, w: 0.18, h: 0.18,
      fill: { color: labs[i].color },
      rectRadius: 0.02
    });
    slide.addText(labs[i].name, {
      x: 0.62 + i * 1.3, y: 0.78, w: 1.05, h: 0.25,
      fontSize: 9, fontFace: "Calibri",
      color: "5A6B7C", margin: 0
    });
  }

  // Data table
  const data = [
    {
      benchmark: "SWE Atlas – Test Writing",
      rows: [
        { model: "GPT-5.4-xHigh (Codex CLI)", score: "44.36", lab: "openai" },
        { model: "GPT-5.4-xHigh (Mini-SWE)", score: "40.00", lab: "openai" },
        { model: "GPT-5.3-Codex-Xhigh", score: "38.98", lab: "openai" }
      ]
    },
    {
      benchmark: "SWE Atlas – Codebase QnA",
      rows: [
        { model: "GPT 5.4 xHigh (Codex)", score: "40.80", lab: "openai" },
        { model: "GPT 5.4 xHigh (Mini-SWE)", score: "36.30", lab: "openai" },
        { model: "Opus 4.6 (Claude Code)", score: "33.30", lab: "anthropic" }
      ]
    },
    {
      benchmark: "MCP Atlas (Tool Use)",
      rows: [
        { model: "Muse Spark", score: "78.30", lab: "muse" },
        { model: "Claude Opus 4.6", score: "75.80", lab: "anthropic" },
        { model: "Gemini 3.1 Pro Preview", score: "73.90", lab: "google" }
      ]
    },
    {
      benchmark: "SWE-Bench Pro (Public)",
      rows: [
        { model: "GPT-5.4-pro (xHigh)", score: "59.10", lab: "openai" },
        { model: "Muse Spark", score: "55.00", lab: "muse" },
        { model: "Claude Opus 4.6", score: "51.90", lab: "anthropic" }
      ]
    },
    {
      benchmark: "SWE-Bench Pro (Private)",
      rows: [
        { model: "Claude Opus 4.6", score: "47.10", lab: "anthropic" },
        { model: "Muse Spark", score: "44.70", lab: "muse" },
        { model: "GPT-5.4-pro (xHigh)", score: "43.40", lab: "openai" }
      ]
    }
  ];

  const labColorMap = {
    openai: theme.primary,
    google: theme.secondary,
    anthropic: theme.accent,
    muse: "e76f51"
  };

  // Build table rows
  const headerRow = [
    { text: "Benchmark", options: { fill: { color: theme.primary }, color: "FFFFFF", bold: true, fontSize: 10, fontFace: "Calibri", align: "left", margin: [3, 5, 3, 5] } },
    { text: "#1 Model", options: { fill: { color: theme.primary }, color: "FFFFFF", bold: true, fontSize: 10, fontFace: "Calibri", align: "left", margin: [3, 5, 3, 5] } },
    { text: "Score", options: { fill: { color: theme.primary }, color: "FFFFFF", bold: true, fontSize: 10, fontFace: "Calibri", align: "center", margin: [3, 5, 3, 5] } },
    { text: "#2 Model", options: { fill: { color: theme.primary }, color: "FFFFFF", bold: true, fontSize: 10, fontFace: "Calibri", align: "left", margin: [3, 5, 3, 5] } },
    { text: "Score", options: { fill: { color: theme.primary }, color: "FFFFFF", bold: true, fontSize: 10, fontFace: "Calibri", align: "center", margin: [3, 5, 3, 5] } },
    { text: "#3 Model", options: { fill: { color: theme.primary }, color: "FFFFFF", bold: true, fontSize: 10, fontFace: "Calibri", align: "left", margin: [3, 5, 3, 5] } },
    { text: "Score", options: { fill: { color: theme.primary }, color: "FFFFFF", bold: true, fontSize: 10, fontFace: "Calibri", align: "center", margin: [3, 5, 3, 5] } }
  ];

  const tableRows = [headerRow];

  data.forEach((d, dIdx) => {
    const bgColor = dIdx % 2 === 0 ? "FFFFFF" : "F0F4F5";
    tableRows.push([
      { text: d.benchmark, options: { fill: { color: bgColor }, fontSize: 9, fontFace: "Calibri", color: theme.primary, bold: true, align: "left", margin: [3, 4, 3, 4] } },
      { text: d.rows[0].model, options: { fill: { color: bgColor }, fontSize: 9, fontFace: "Calibri", color: labColorMap[d.rows[0].lab], align: "left", margin: [3, 4, 3, 4] } },
      { text: d.rows[0].score, options: { fill: { color: bgColor }, fontSize: 9, fontFace: "Calibri", color: theme.primary, bold: true, align: "center", margin: [3, 4, 3, 4] } },
      { text: d.rows[1].model, options: { fill: { color: bgColor }, fontSize: 9, fontFace: "Calibri", color: labColorMap[d.rows[1].lab], align: "left", margin: [3, 4, 3, 4] } },
      { text: d.rows[1].score, options: { fill: { color: bgColor }, fontSize: 9, fontFace: "Calibri", color: "5A6B7C", align: "center", margin: [3, 4, 3, 4] } },
      { text: d.rows[2].model, options: { fill: { color: bgColor }, fontSize: 9, fontFace: "Calibri", color: labColorMap[d.rows[2].lab], align: "left", margin: [3, 4, 3, 4] } },
      { text: d.rows[2].score, options: { fill: { color: bgColor }, fontSize: 9, fontFace: "Calibri", color: "5A6B7C", align: "center", margin: [3, 4, 3, 4] } }
    ]);
  });

  slide.addTable(tableRows, {
    x: 0.3, y: 1.15, w: 9.4,
    colW: [1.85, 1.6, 0.6, 1.6, 0.6, 1.6, 0.6],
    border: { pt: 0.5, color: "D8E0E5" },
    rowH: [0.32, 0.32, 0.32, 0.32, 0.32, 0.32]
  });

  // Callout box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 3.7, w: 9.2, h: 0.6,
    fill: { color: "EDF5F7" },
    rectRadius: 0.03
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 3.7, w: 0.06, h: 0.6,
    fill: { color: theme.primary }
  });
  slide.addText("GPT-5.4 variants hold #1 on 3 of 5 agentic benchmarks. Claude Opus 4.6 leads SWE-Bench Pro (Private) on real-world repos. Muse Spark claims #1 on MCP Atlas tool use at 78.30.", {
    x: 0.6, y: 3.72, w: 8.8, h: 0.55,
    fontSize: 11, fontFace: "Calibri",
    color: theme.primary,
    margin: 0
  });

  // Score bars visualization (mini grouped bars for top 3 benchmarks)
  const barData = [
    { label: "SWE Atlas\nTest Writing", values: [44.36, 40.00, 38.98], labKeys: ["openai", "openai", "openai"] },
    { label: "SWE-Bench\nPro (Public)", values: [59.10, 55.00, 51.90], labKeys: ["openai", "muse", "anthropic"] },
    { label: "SWE-Bench\nPro (Private)", values: [47.10, 44.70, 43.40], labKeys: ["anthropic", "muse", "openai"] }
  ];

  const barStartY = 4.5;
  const barMaxH = 0.7;
  const maxVal = 65;

  barData.forEach((bd, bi) => {
    const groupX = 0.5 + bi * 3.2;

    // Label
    slide.addText(bd.label, {
      x: groupX, y: 4.35, w: 2.8, h: 0.3,
      fontSize: 8, fontFace: "Calibri",
      color: "5A6B7C", align: "center", margin: 0
    });

    // Bars
    for (let j = 0; j < 3; j++) {
      const barW = 0.25;
      const barH = (bd.values[j] / maxVal) * barMaxH;
      const bx = groupX + 0.3 + j * 0.85;
      const by = barStartY + barMaxH - barH;

      slide.addShape(pres.shapes.RECTANGLE, {
        x: bx, y: by, w: barW, h: barH,
        fill: { color: labColorMap[bd.labKeys[j]] },
        rectRadius: 0.02
      });

      // Score label on bar
      slide.addText(String(bd.values[j]), {
        x: bx - 0.1, y: by - 0.18, w: barW + 0.2, h: 0.18,
        fontSize: 7, fontFace: "Calibri",
        color: "5A6B7C", align: "center", margin: 0
      });
    }
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.secondary }
  });
  slide.addText("3", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Calibri",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "264653", secondary: "2a9d8f", accent: "e9c46a", light: "f4a261", bg: "f7f7f7" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-03-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

