const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 4,
  title: 'GPT-5.4-Pro Leads Humanity\'s Last Exam at 44.3%'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("GPT-5.4-Pro Leads Humanity's Last Exam at 44.3% — Scores Remain Below 50%", {
    x: 0.4, y: 0.2, w: 9.2, h: 0.55,
    fontSize: 22, fontFace: "Georgia",
    color: theme.primary, bold: true,
    margin: 0, fit: "shrink"
  });

  // Subtitle callout
  slide.addText("Even top scores are well below saturation, indicating these benchmarks still challenge frontier models.", {
    x: 0.4, y: 0.78, w: 9, h: 0.3,
    fontSize: 12, fontFace: "Calibri",
    color: "5A6B7C", margin: 0
  });

  // Horizontal bar chart using shapes - HLE
