    openai: theme.primary,
    google: theme.secondary,
    anthropic: theme.accent,
    muse: "e76f51"
  };

  // Chart area
  const chartX = 0.5;
  const chartY = 1.25;
  const chartW = 5.5;
  const maxScore = 50;
  const barH = 0.22;
  const barGap = 0.06;

  // HLE Section
  slide.addText("Humanity's Last Exam", {
    x: chartX, y: chartY, w: 3, h: 0.3,
    fontSize: 13, fontFace: "Georgia",
    color: theme.primary, bold: true, margin: 0
  });

  const hleData = [
    { model: "GPT-5.4-pro", score: 44.32, lab: "openai" },
    { model: "Muse Spark", score: 40.56, lab: "muse" },
    { model: "Gemini-3-pro-preview", score: 37.52, lab: "google" }
  ];

  let curY = chartY + 0.35;
  hleData.forEach((d) => {
    const barW = (d.score / maxScore) * chartW;
    // Model name
    slide.addText(d.model, {
      x: chartX, y: curY, w: 2.2, h: barH,
      fontSize: 9, fontFace: "Calibri",
      color: labColorMap[d.lab], margin: 0, valign: "middle"
    });
    // Bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: chartX + 2.2, y: curY + 0.02, w: barW, h: barH - 0.04,
      fill: { color: labColorMap[d.lab] },
      rectRadius: 0.02
    });
    // Score label
    slide.addText(d.score + "%", {
      x: chartX + 2.2 + barW + 0.08, y: curY, w: 0.7, h: barH,
      fontSize: 9, fontFace: "Calibri",
      color: theme.primary, bold: true, margin: 0, valign: "middle"
    });
    curY += barH + barGap;
  });

  // 50% reference line
  const refX = chartX + 2.2 + (50 / maxScore) * chartW;
  slide.addShape(pres.shapes.LINE, {
    x: chartX + 2.2, y: chartY + 0.33, w: chartW, h: 0,
    line: { color: "D0D8E0", width: 0.5, dashType: "dash" }
  });

  // EnigmaEval Section
  const enigmaY = curY + 0.15;
  slide.addText("EnigmaEval", {
    x: chartX, y: enigmaY, w: 3, h: 0.3,
    fontSize: 13, fontFace: "Georgia",
    color: theme.primary, bold: true, margin: 0
  });

  const enigmaData = [
    { model: "GPT-5.4-pro", score: 23.82, lab: "openai" },
    { model: "Gemini-3.1", score: 19.76, lab: "google" },
    { model: "GPT-5-pro-2025", score: 18.75, lab: "openai" }
  ];

  const enigmaMax = 30;
  curY = enigmaY + 0.35;
