const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 7,
  title: 'OpenAI, Google, and Anthropic Each Claim #1 Across Different Domains'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("OpenAI, Google, and Anthropic Each Claim #1 Across Different Domains", {
    x: 0.4, y: 0.2, w: 9.2, h: 0.5,
    fontSize: 22, fontFace: "Georgia",
    color: theme.primary, bold: true,
    margin: 0, fit: "shrink"
  });

  // Heatmap matrix - benchmarks (rows) x labs (columns)
  // Color: if lab is #1, fill with lab color; otherwise light gray

  const labHeaders = ["OpenAI", "Google", "Anthropic", "Muse Spark"];
  const labColors = [theme.primary, theme.secondary, theme.accent, "e76f51"];

  // Benchmark data: [isOpenAI#1, isGoogle#1, isAnthropic#1, isMuseSpark#1, score]
  const benchmarks = [
    { name: "SWE Atlas – Test Writing", domain: "Agentic", wins: [1, 0, 0, 0], score: "44.36" },
    { name: "SWE Atlas – Codebase QnA", domain: "Agentic", wins: [1, 0, 0, 0], score: "40.80" },
    { name: "MCP Atlas (Tool Use)", domain: "Agentic", wins: [0, 0, 0, 1], score: "78.30" },
    { name: "SWE-Bench Pro (Public)", domain: "Agentic", wins: [1, 0, 0, 0], score: "59.10" },
    { name: "SWE-Bench Pro (Private)", domain: "Agentic", wins: [0, 0, 1, 0], score: "47.10" },
    { name: "Humanity's Last Exam", domain: "Frontier", wins: [1, 0, 0, 0], score: "44.32" },
    { name: "HLE (Text Only)", domain: "Frontier", wins: [1, 0, 0, 0], score: "45.32" },
    { name: "EnigmaEval", domain: "Frontier", wins: [1, 0, 0, 0], score: "23.82" },
    { name: "MultiChallenge", domain: "Frontier", wins: [0, 0, 0, 1], score: "75.52" },
    { name: "MultiNRC", domain: "Frontier", wins: [1, 0, 0, 0], score: "65.20" },
    { name: "SciPredict", domain: "Frontier", wins: [0, 1, 0, 0], score: "25.27" },
    { name: "MASK (Honesty)", domain: "Safety", wins: [0, 0, 1, 0], score: "96.28" },
    { name: "PropensityBench", domain: "Safety", wins: [1, 0, 0, 0], score: "10.50" },
    { name: "Prof. Reasoning – Legal", domain: "Safety", wins: [0, 0, 1, 0], score: "52.27" },
    { name: "Prof. Reasoning – Finance", domain: "Safety", wins: [0, 0, 1, 0], score: "53.28" },
    { name: "AudioMultiCh. (Text)", domain: "Multi.", wins: [0, 1, 0, 0], score: "54.65" },
    { name: "AudioMultiCh. (Audio)", domain: "Multi.", wins: [0, 1, 0, 0], score: "36.06" },
    { name: "VISTA", domain: "Multi.", wins: [0, 1, 0, 0], score: "54.65" },
    { name: "VisualToolBench", domain: "Multi.", wins: [1, 0, 0, 0], score: "29.17" }
  ];

  const tableX = 0.3;
  const tableY = 0.85;
  const benchW = 2.2;
  const domainW = 0.7;
  const labColW = 0.88;
  const scoreW = 0.6;
  const rowH = 0.22;
  const headerH = 0.35;

  // Build header row
  const headerRow = [
    { text: "Benchmark", options: { fill: { color: theme.primary }, color: "FFFFFF", bold: true, fontSize: 9, fontFace: "Calibri", align: "left", margin: [2, 4, 2, 4] } },
    { text: "Domain", options: { fill: { color: theme.primary }, color: "FFFFFF", bold: true, fontSize: 8, fontFace: "Calibri", align: "center", margin: [2, 3, 2, 3] } }
  ];
  labHeaders.forEach((lab) => {
    headerRow.push({ text: lab, options: { fill: { color: theme.primary }, color: "FFFFFF", bold: true, fontSize: 8, fontFace: "Calibri", align: "center", margin: [2, 2, 2, 2] } });
  });
  headerRow.push({ text: "Score", options: { fill: { color: theme.primary }, color: "FFFFFF", bold: true, fontSize: 8, fontFace: "Calibri", align: "center", margin: [2, 2, 2, 2] } });

  const tableRows = [headerRow];

  benchmarks.forEach((b, bIdx) => {
    const bgColor = bIdx % 2 === 0 ? "FFFFFF" : "F5F8F9";
    const row = [
      { text: b.name, options: { fill: { color: bgColor }, fontSize: 7, fontFace: "Calibri", color: theme.primary, align: "left", margin: [2, 3, 2, 3] } },
      { text: b.domain, options: { fill: { color: bgColor }, fontSize: 7, fontFace: "Calibri", color: "8A9BAC", align: "center", margin: [2, 2, 2, 2] } }
    ];
    b.wins.forEach((w, wi) => {
      if (w === 1) {
        row.push({ text: "#1", options: { fill: { color: labColors[wi] }, fontSize: 8, fontFace: "Calibri", color: "FFFFFF", bold: true, align: "center", margin: [2, 2, 2, 2] } });
      } else {
        row.push({ text: "", options: { fill: { color: bgColor }, fontSize: 7, fontFace: "Calibri", align: "center", margin: [2, 2, 2, 2] } });
      }
    });
    row.push({ text: b.score, options: { fill: { color: bgColor }, fontSize: 7, fontFace: "Calibri", color: "5A6B7C", align: "center", margin: [2, 2, 2, 2] } });
    tableRows.push(row);
  });

  slide.addTable(tableRows, {
    x: tableX, y: tableY, w: 9.4,
    colW: [benchW, domainW, labColW, labColW, labColW, labColW, scoreW],
    border: { pt: 0.5, color: "D8E0E5" },
    rowH: [headerH, ...Array(benchmarks.length).fill(rowH)]
  });

  // Summary bar at bottom
  const summaryY = 5.15;

  // Count #1s per lab
  const winCounts = [0, 0, 0, 0];
  benchmarks.forEach(b => b.wins.forEach((w, i) => { if (w) winCounts[i]++; }));

  slide.addText([
    { text: "OpenAI ", options: { bold: true, color: theme.primary, fontSize: 9 } },
    { text: winCounts[0] + " #1s  |  ", options: { color: "5A6B7C", fontSize: 9 } },
    { text: "Google ", options: { bold: true, color: theme.secondary, fontSize: 9 } },
    { text: winCounts[1] + " #1s  |  ", options: { color: "5A6B7C", fontSize: 9 } },
    { text: "Anthropic ", options: { bold: true, color: theme.accent, fontSize: 9 } },
    { text: winCounts[2] + " #1s  |  ", options: { color: "5A6B7C", fontSize: 9 } },
    { text: "Muse Spark ", options: { bold: true, color: "e76f51", fontSize: 9 } },
    { text: winCounts[3] + " #1s", options: { color: "5A6B7C", fontSize: 9 } }
  ], {
    x: 0.4, y: summaryY, w: 8.5, h: 0.25,
    fontFace: "Calibri", margin: 0
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.secondary }
  });
  slide.addText("7", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Calibri",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "264653", secondary: "2a9d8f", accent: "e9c46a", light: "f4a261", bg: "f7f7f7" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-07-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

